class Solution:
    def numIslands2(self, m: int, n: int, positions: list[list[int]]) -> list[int]:
        parent = {}
        rank = {}
        count = 0
        result = []
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            nonlocal count
            ra, rb = find(a), find(b)
            if ra == rb: return
            if rank.get(ra,0) < rank.get(rb,0): ra, rb = rb, ra
            parent[rb] = ra
            if rank.get(ra,0) == rank.get(rb,0):
                rank[ra] = rank.get(ra,0) + 1
            count -= 1
        for r, c in positions:
            if (r, c) in parent:
                result.append(count)
                continue
            parent[(r,c)] = (r,c)
            count += 1
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) in parent:
                    union((r,c),(nr,nc))
            result.append(count)
        return result

